import zipfile, re
import xml.etree.ElementTree as ET

NS = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main',
      'r': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships'}

def col_to_idx(ref):
    m = re.match(r'([A-Z]+)(\d+)', ref)
    col = 0
    for ch in m.group(1):
        col = col * 26 + (ord(ch) - ord('A') + 1)
    return col - 1, int(m.group(2))

with zipfile.ZipFile('budget.xlsx') as z:
    names = z.namelist()
    print("ZIP contents:")
    for n in names:
        print(" ", n)

    wb = ET.fromstring(z.read('xl/workbook.xml'))
    sheets = []
    for sh in wb.iter('{%s}sheet' % NS['m']):
        sheets.append((sh.get('name'), sh.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id'), sh.get('sheetId')))
    print("\nSheets:", sheets)

    # map r:id -> target
    rels = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
    rel_map = {}
    for rel in rels:
        rel_map[rel.get('Id')] = rel.get('Target')
    print("Rel map:", rel_map)

    # shared strings
    shared = []
    if 'xl/sharedStrings.xml' in names:
        ss = ET.fromstring(z.read('xl/sharedStrings.xml'))
        for si in ss.iter('{%s}si' % NS['m']):
            text = ''.join(t.text or '' for t in si.iter('{%s}t' % NS['m']))
            shared.append(text)
    print("\nShared strings count:", len(shared))

    for name, rid, sid in sheets:
        target = rel_map.get(rid, '')
        if not target.startswith('xl/'):
            target = 'xl/' + target.lstrip('/')
        print(f"\n=== Sheet '{name}' -> {target} ===")
        ws = ET.fromstring(z.read(target))
        for c in ws.iter('{%s}c' % NS['m']):
            ref = c.get('r')
            t = c.get('t')
            v = c.find('{%s}v' % NS['m'])
            isel = c.find('{%s}is' % NS['m'])
            if v is not None:
                val = v.text
                if t == 's':
                    val = shared[int(val)]
                elif t == 'b':
                    val = (val == '1')
                elif t == 'str':
                    pass
            elif isel is not None:
                val = ''.join(x.text or '' for x in isel.iter('{%s}t' % NS['m']))
            else:
                val = None
            f = c.find('{%s}f' % NS['m'])
            formula = f.text if f is not None else None
            if val is not None or formula is not None:
                print(f"{ref}: value={val!r} type={t} formula={formula!r}")

